CREATE TABLE IF NOT EXISTS integrationOAuthStates (id INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, provider VARCHAR(64) NOT NULL, state VARCHAR(180) NOT NULL UNIQUE, codeVerifier VARCHAR(256) NOT NULL, redirectUri VARCHAR(1000) NOT NULL, expiresAt TIMESTAMP NOT NULL, createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX integrationOAuthStates_user_idx (userId), INDEX integrationOAuthStates_expires_idx (expiresAt));
